 if '--mutations' in sys.argv:
  mutations += [('hidden-macro-binding','if (item.hidden && !item.allowsKeyEquivalentWhenHidden) return;',';'),('hidden-menu','if (match.menuItem.hidden && !match.menuItem.allowsKeyEquivalentWhenHidden) continue;',';'),('empty-initial-list','self.searchingByKey && self.searchEvent != nil ? (NSInteger)self.searchMatches.count','self.searchingByKey ? (NSInteger)self.searchMatches.count'),('modifier-only-event','if (event.type != NSEventTypeKeyDown) { return YES; }',';'),('cancel-click-ignored','if (clear) { self.clearKey(); }','if (NO) { self.clearKey(); }'),('cancel-keeps-focus-away','if (window != nil) { [window makeFirstResponder:self.keySearchView]; }\n}\n- (BOOL)handleKeySearchEvent:','}\n- (BOOL)handleKeySearchEvent:'),('outside-focus-keeps-search','[view isDescendantOf:commands]) { return; }\n    [self stopKeySearch];','[view isDescendantOf:commands]) { return; }'),('cancel-without-key','return self.clearKey != nil && self.searchField.stringValue.length > 0;','return self.clearKey != nil;'),('conflict-ends-recording','if (conflict != nil) { [self showRecordingError:conflict]; return; }','if (conflict != nil) { [self endRecording]; return; }'),('escape-is-recorded',"if (!flags && (c == 27 || c == '\\r' || c == 3)) { [self endRecording]; return YES; }","if (!flags && (c == '\\r' || c == 3)) { [self endRecording]; return YES; }"),('click-unselected-records','if (row < 0 || row != table.rowSelectedAtMouseDown || table.clickedColumn','if (row < 0 || table.clickedColumn'),('status-hides-refusal','NSString *error = self.editingCommand != nil ? self.recordingError : nil;','NSString *error = nil;')]
 for name,old,new in mutations:
  assert original.count(old)==1,(name,original.count(old));changed=original.replace(old,new)
